inp=G['Test input']; demo_in=G['Demo pair 1 input']; demo_out=G['Demo pair 1 output']
H=len(inp); W=len(inp[0])

def objects(g):
    seen=set(); objs=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<len(g) and 0<=b<len(g[0]) and g[a][b]==col and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
                objs.append((col,cells))
    return objs

def solve(g, order_key, diag=False):
    g=[row[:] for row in g]
    objs=objects(g)
    objs.sort(key=order_key)
    occupied=set((r,c) for r in range(H) for c in range(W) if g[r][c])
    for col,cells in objs:
        occupied-=set(cells)
        k=0
        while True:
            moved=[(r,c+k+1) for r,c in cells]
            if any(c+k+1>=W for r,c in cells): break  # would hit edge
            bad=False
            for (r,c) in moved:
                if (r,c) in occupied: bad=True; break
                if not diag and (r,c+1) in occupied: bad=True; break
                if diag:
                    for d in((0,1),(1,0),(-1,0),(1,1),(-1,-1),(1,-1),(-1,1)):
                        if (r+d[0],c+d[1]) in occupied: bad=True; break
                    if bad: break
            if bad: break
            k+=1
        for r,c in cells: g[r][c]=0
        for r,c in cells: g[r][c+k]=col
        occupied|=set((r,c+k) for r,c in cells)
    return g

